        private static readonly Dictionary<string, int> Index = BuildIndex();
        private static Dictionary<string, int> BuildIndex()
        {
            var index = new Dictionary<string, int>(Keys.Length, StringComparer.Ordinal);
            for (int i = 0; i < Keys.Length; i++)
            {
                index[Keys[i]] = i;
            }

            return index;
        }

        internal static int LocaleColumn(string locale)
        {
            if (locale == null)
            {
                return -1;
            }

            for (int i = 0; i < Locales.Length; i++)
            {
                if (string.Equals(Locales[i], locale, StringComparison.OrdinalIgnoreCase))
                {
                    return i;
                }
            }

            return -1;
        }

        /// <summary>
        /// Uebersetzung fuer <paramref name = "locale"/>; false fuer
        /// unbekannte Sprache oder unbekannten Text. Wirft nie.
        /// </summary>
        internal static bool TryTranslate(string locale, string german, out string translated)
        {
            translated = null;
            try
            {
                int column = LocaleColumn(locale);
                int row;
                if (column < 0 || german == null || !Index.TryGetValue(german, out row))
                {
                    return false;
                }

                translated = Rows[row][column];
                return !string.IsNullOrEmpty(translated);
            }
            catch (Exception)
            {
                translated = null;
                return false;
            }
        }
    }
